(()=>{if((window.scc??(window.scc={})).faq)return;window.scc.faq=!0;const a=e=>{const t=e.querySelector(".faq-head"),o=e.querySelector(".faq-body");if(!t||!o)return;e.classList.remove("is-open"),t.setAttribute("role","button"),t.setAttribute("tabindex","0"),t.setAttribute("aria-expanded","false");const s=()=>{const n=!e.classList.contains("is-open");e.classList.toggle("is-open",n),t.setAttribute("aria-expanded",String(n))};t.addEventListener("click",s),t.addEventListener("keydown",n=>{n.key!=="Enter"&&n.key!==" "||(n.preventDefault(),s())})},r=()=>{for(const e of document.querySelectorAll(".faq-section"))e.dataset.faqPret||(e.dataset.faqPret="1",e.querySelectorAll(".faq-item").forEach(a))};document.readyState==="loading"?document.addEventListener("DOMContentLoaded",r,{once:!0}):r()})();
